mapper.select:
SELECT c.id AS caseId, c.case_no AS caseNo, c.patient_id AS patientId, p.patient_no AS patientNo, c.patient_age AS patientAge, c.patient_gender AS patientGender, c.eye_side AS eyeSide, c.workflow_status AS workflowStatus, JSON_UNQUOTE(JSON_EXTRACT(qr.result_json, '$.qualityStatus')) AS qualityStatus, CAST(JSON_UNQUOTE(JSON_EXTRACT(qr.result_json, '$.score')) AS DECIMAL(10,2)) AS qualityScore, st.status AS segmentationStatus, rv.status AS reviewStatus, sr.status AS reportStatus, st.id AS latestTaskId, c.updated_at AS updatedAt FROM medical_case c JOIN patient_profile p ON p.id = c.patient_id
LEFT JOIN analysis_task qt ON qt.id = ( SELECT qt0.id FROM analysis_task qt0 WHERE qt0.case_id = c.id AND qt0.task_type = 'IMAGE_QUALITY_CHECK' ORDER BY qt0.updated_at DESC, qt0.id DESC LIMIT 1 ) LEFT JOIN analysis_result qr ON qr.task_id = qt.id
ORDER BY c.updated_at DESC, c.id DESC LIMIT #{offset}, #{pageSize}

