WHERE c.assigned_doctor_id = #{doctorId} AND c.status != 'DELETED' AND t.task_type = #{criteria.taskType}
AND t.status IN ('CREATED','WAITING') AND t.status IN ('RUNNING','RETRYING') AND t.status = 'FAILED' AND t.status = 'SUCCESS'
AND t.updated_at >= CURRENT_DATE AND t.updated_at >= DATE_SUB(NOW(), INTERVAL 7 DAY) AND t.updated_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)

